'use client'

import { useState, useEffect, useRef, useCallback } from 'react'
import { api } from '../api'
import { useShopInfo } from '../useShopInfo'
import { openEventStream } from '../utils/eventStream'
import LinkifiedText from './LinkifiedText'
import { AUTH_EVENT, chatScope, clearChatStorage, migrateLegacyChat, readChat, readSeen, writeChat, writeSeen } from '../utils/chatStorage'

// Cuộc trò chuyện + token bí mật (có mã mà thiếu token thì máy chủ không cho đọc) lưu theo TÀI KHOẢN, xem utils/chatStorage.js.
const FALLBACK_POLL_MS = 30000 // tin nhắn tới tức thì qua luồng thời gian thực; vòng tải lại này chỉ để dự phòng

export default function ChatWidget() {
  const [open, setOpen] = useState(false)
  const [scope, setScope] = useState(() => {
    const s = chatScope()
    migrateLegacyChat(s)
    return s
  })
  const [conversationId, setConversationId] = useState(() => readChat(chatScope()).id)
  const [chatToken, setChatToken] = useState(() => readChat(chatScope()).token)
  const [messages, setMessages] = useState([])
  const [name, setName] = useState('')
  const [phone, setPhone] = useState('')
  const [draft, setDraft] = useState('')
  const [starting, setStarting] = useState(false)
  const [sending, setSending] = useState(false)
  const [error, setError] = useState('')
  const [hasUnread, setHasUnread] = useState(false)
  const scrollRef = useRef(null)
  const convRef = useRef(conversationId)
  convRef.current = conversationId
  const { shopInfo, contact } = useShopInfo()

  const authOptions = useCallback(() => (chatToken ? { headers: { 'X-Chat-Token': chatToken } } : undefined), [chatToken])

  const load = useCallback(async () => {
    if (!conversationId) return
    try {
      const data = await api.get(`/chat/conversations/${conversationId}/messages`, authOptions())
      if (convRef.current !== conversationId) return // đã đổi tài khoản / cuộc trò chuyện trong lúc chờ: bỏ kết quả cũ
      // Cuộc trò chuyện tạo trước khi có token: máy chủ cấp token ở lần vào này, lưu lại để dùng từ giờ.
      if (data.token) {
        writeChat(scope, { id: conversationId, token: data.token })
        setChatToken(data.token)
      }
      setMessages(data.messages)

      const lastAdminMsg = [...data.messages].reverse().find((m) => m.sender === 'ADMIN')
      const lastSeen = readSeen(scope)
      if (lastAdminMsg && lastAdminMsg.id !== lastSeen) {
        setHasUnread(!open)
      }
    } catch (err) {
      // Mã/token không còn hợp lệ (404): bỏ cuộc trò chuyện đã nhớ để khách bắt đầu cuộc mới thay vì kẹt ở khung trống.
      if (err.status === 404) {
        clearChatStorage(scope)
        setConversationId(null)
        setChatToken(null)
        setMessages([])
      }
      // Lỗi khác (backend offline...): im lặng, khung chat chỉ đứng yên.
    }
  }, [conversationId, open, authOptions, scope])

  const loadRef = useRef(load)
  loadRef.current = load

  // Đăng nhập / đăng xuất (auth.js phát AUTH_EVENT): chuyển sang bộ dữ liệu chat của đúng tài khoản.
  useEffect(() => {
    const sync = () => setScope(chatScope())
    window.addEventListener(AUTH_EVENT, sync)
    return () => window.removeEventListener(AUTH_EVENT, sync)
  }, [])

  // Theo tài khoản: đổi tài khoản thì bỏ sạch những gì đang hiện của người trước. Tài khoản đã đăng nhập thì xóa dữ liệu chat của khách vãng lai trên máy
  // (máy dùng chung, không để lại cho người sau) rồi lấy cuộc trò chuyện chuẩn của tài khoản từ máy chủ.
  const scopeRef = useRef(scope)
  useEffect(() => {
    if (scopeRef.current !== scope) {
      scopeRef.current = scope
      const saved = readChat(scope)
      setConversationId(saved.id)
      setChatToken(saved.token)
      setMessages([])
      setHasUnread(false)
      setOpen(false)
      setDraft('')
      setName('')
      setPhone('')
      setError('')
    }
    if (scope === 'guest') return undefined
    clearChatStorage('guest')
    let cancelled = false
    api
      .get('/chat/mine')
      .then((data) => {
        if (cancelled || !data.conversation) return
        writeChat(scope, { id: data.conversation.id, token: data.token })
        setConversationId(data.conversation.id)
        setChatToken(data.token)
        setMessages(data.messages)
      })
      .catch(() => {}) // máy chủ tắt: dùng dữ liệu đã lưu theo tài khoản
    return () => {
      cancelled = true
    }
  }, [scope])

  useEffect(() => {
    load()
    const id = setInterval(load, FALLBACK_POLL_MS)
    return () => clearInterval(id)
  }, [load])

  // Thời gian thực: admin trả lời là tin nhắn hiện ngay, không phải chờ lần tải lại.
  useEffect(() => {
    if (!conversationId) return undefined
    return openEventStream(`/chat/conversations/${conversationId}/stream`, () => loadRef.current(), chatToken ? { 'X-Chat-Token': chatToken } : undefined)
  }, [conversationId, chatToken])

  useEffect(() => {
    if (open && scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight
    }
  }, [messages, open])

  useEffect(() => {
    if (open && messages.length > 0) {
      const lastAdminMsg = [...messages].reverse().find((m) => m.sender === 'ADMIN')
      if (lastAdminMsg) writeSeen(scope, lastAdminMsg.id)
      setHasUnread(false)
    }
  }, [open, messages, scope])

  async function handleStart() {
    if (!name.trim()) {
      setError('Vui lòng nhập tên của bạn.')
      return
    }
    setStarting(true)
    setError('')
    try {
      const conv = await api.post('/chat/conversations', { name: name.trim(), phone: phone.trim() })
      writeChat(scope, { id: conv.id, token: conv.token })
      setChatToken(conv.token)
      setConversationId(conv.id)
    } catch (err) {
      setError(err.message)
    } finally {
      setStarting(false)
    }
  }

  async function handleSend() {
    if (!draft.trim() || !conversationId) return
    setSending(true)
    const content = draft.trim()
    setDraft('')
    try {
      await api.post(`/chat/conversations/${conversationId}/messages`, { content, sender: 'CUSTOMER' }, authOptions())
      await load()
    } catch (err) {
      setError(err.message)
    } finally {
      setSending(false)
    }
  }

  return (
    <div className="chat-widget">
      {/* Nút ưu đãi nổi: nằm trên cùng cột nút chat/gọi ở góc phải dưới, nhấp nháy nhẹ để thu hút mà không gây khó chịu */}
      <a className="offer-fab" href="/#deal" aria-label="Xem ưu đãi hôm nay">
        <svg className="offer-fab-icon" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <path d="M20.6 13.4 13.4 20.6a2 2 0 0 1-2.8 0L3 13V3h10l7.6 7.6a2 2 0 0 1 0 2.8z" />
          <circle cx="7.5" cy="7.5" r="1.2" fill="currentColor" />
        </svg>
        <span>Ưu đãi hôm nay</span>
      </a>
      {open && (
        <div className="chat-panel">
          <div className="chat-panel-head">
            <div>
              <strong>Clevinium hỗ trợ</strong>
              <span>Thường phản hồi trong vài phút</span>
            </div>
            <button className="chat-panel-close" onClick={() => setOpen(false)} aria-label="Đóng chat">
              ✕
            </button>
          </div>

          {!conversationId ? (
            <div className="chat-intake">
              <p>Để lại thông tin để đội ngũ Clevinium hỗ trợ bạn nhanh nhất.</p>
              <input
                className="chat-input"
                placeholder="Tên của bạn *"
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
              <input
                className="chat-input"
                placeholder="Số điện thoại (không bắt buộc)"
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
              />
              {error && <p className="chat-error">{error}</p>}
              <button className="btn btn-accent chat-start-btn" onClick={handleStart} disabled={starting}>
                {starting ? 'Đang kết nối...' : 'Bắt đầu trò chuyện'}
              </button>
            </div>
          ) : (
            <>
              <div className="chat-messages" ref={scrollRef}>
                {messages.length === 0 ? (
                  <p className="chat-empty">Gửi tin nhắn đầu tiên cho chúng tôi nhé!</p>
                ) : (
                  messages.map((m) => (
                    <div key={m.id} className={`chat-bubble ${m.sender === 'CUSTOMER' ? 'chat-bubble-me' : 'chat-bubble-admin'}`}>
                      <LinkifiedText text={m.content} />
                    </div>
                  ))
                )}
              </div>
              {error && <p className="chat-error">{error}</p>}
              <div className="chat-input-row">
                <input
                  className="chat-input"
                  placeholder="Nhập tin nhắn..."
                  value={draft}
                  onChange={(e) => setDraft(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                />
                <button className="btn btn-accent" onClick={handleSend} disabled={sending || !draft.trim()}>
                  Gửi
                </button>
              </div>
            </>
          )}
        </div>
      )}

      {/* Kênh tư vấn nhanh cho khách đang phân vân (link Zalo/Facebook sửa ở dashboard > Cài đặt > Nội dung trang) */}
      <div className="quick-contact">
        <a className="quick-contact-btn quick-call" href={`tel:${shopInfo.hotline.replace(/[^\d+]/g, '')}`} aria-label={`Gọi ${shopInfo.hotline}`}>
          <span aria-hidden="true">📞</span>
          <b>Gọi ngay</b>
        </a>
        {contact?.zaloUrl && (
          <a className="quick-contact-btn quick-zalo" href={contact.zaloUrl} target="_blank" rel="noopener noreferrer" aria-label="Chat Zalo">
            <span aria-hidden="true">Z</span>
            <b>Zalo</b>
          </a>
        )}
        {contact?.facebookUrl && (
          <a className="quick-contact-btn quick-fb" href={contact.facebookUrl} target="_blank" rel="noopener noreferrer" aria-label="Chat Messenger">
            <span aria-hidden="true">f</span>
            <b>Messenger</b>
          </a>
        )}
      </div>

      <button className="chat-bubble-btn" onClick={() => setOpen((o) => !o)} aria-label="Mở chat hỗ trợ">
        {hasUnread && <span className="chat-unread-dot" />}
        {open ? '✕' : '💬'}
      </button>
    </div>
  )
}
