'use client'

import { Suspense, useEffect, useState } from 'react'
import { usePathname } from 'next/navigation'
import { Link, useNavigate } from '@/lib/router'
import SearchBox from './SearchBox'
import ProductsMenu from './ProductsMenu'
import { useShopInfo } from '../useShopInfo'
import { getSession, logout } from '../auth'
import { useCart } from '../context/CartContext'
import { useWishlist } from '../context/WishlistContext'

function formatPrice(n) {
  return n.toLocaleString('vi-VN') + 'đ'
}

export default function Header() {
  // Phiên đăng nhập nằm trong trình duyệt: nạp sau khi mở trang để HTML từ server và lần vẽ đầu của trình duyệt giống nhau.
  const [session, setSession] = useState(null)
  const pathname = usePathname()
  // Đang ở trang chủ mà bấm logo / "Trang chủ" thì tải lại trang về đầu trang (Next chỉ chuyển trong cùng trang nên mặc định không có gì xảy ra).
  const reloadIfHome = (e) => {
    if (pathname !== '/' || e.metaKey || e.ctrlKey || e.shiftKey || e.button !== 0) return
    e.preventDefault()
    // Điều hướng mới tới '/' (thay vì reload) để trình duyệt không khôi phục vị trí cuộn cũ: trang tải lại và nằm ở đầu trang.
    window.scrollTo(0, 0)
    window.location.assign('/')
  }
  useEffect(() => setSession(getSession()), [])
  // Khi trình duyệt rảnh, tải sẵn các trang giỏ hàng / thanh toán / yêu thích / tra cứu đơn để chuyển sang là nhanh.
  useEffect(() => {
    const run = () => import('../clientViews').then((m) => m.preloadShoppingViews())
    if ('requestIdleCallback' in window) {
      const id = window.requestIdleCallback(run, { timeout: 4000 })
      return () => window.cancelIdleCallback(id)
    }
    const t = setTimeout(run, 2000)
    return () => clearTimeout(t)
  }, [])
  const navigate = useNavigate()
  const { totalCount, totalPrice } = useCart()
  const { count: wishCount } = useWishlist()
  const { shopInfo } = useShopInfo()

  function handleLogout() {
    logout()
    setSession(null)
    navigate('/')
  }

  return (
    <header className="header">
      <div className="header-pill">
      <div className="container header-top">
        <Link to="/" onClick={reloadIfHome} className="logo" aria-label={`${shopInfo.name} - về trang chủ`}>
          <svg width="26" height="26" viewBox="0 0 26 26" fill="none">
            <path
              d="M4 3 C4 10 9 12 9 16 C9 20 5 21 5 23"
              stroke="var(--accent)"
              strokeWidth="2"
              fill="none"
            />
            <path
              d="M22 3 C22 10 17 12 17 16 C17 20 21 21 21 23"
              stroke="var(--accent)"
              strokeWidth="2"
              fill="none"
            />
          </svg>
          <span className="logo-text">{shopInfo.name}</span>
        </Link>

        <Suspense fallback={<div className="search-box" />}>
          <SearchBox />
        </Suspense>

        <div className="header-actions">
          <a className="support" href={`tel:${String(shopInfo.hotline).replace(/[^\d+]/g, '')}`} aria-label={`Gọi hotline ${shopInfo.hotline}`}>
            <span className="headset-icon">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                <path
                  d="M4 13a8 8 0 0 1 16 0"
                  stroke="var(--accent)"
                  strokeWidth="1.8"
                  fill="none"
                />
                <rect x="3" y="13" width="4" height="6" rx="2" fill="var(--accent)" />
                <rect x="17" y="13" width="4" height="6" rx="2" fill="var(--accent)" />
              </svg>
            </span>
            <div className="support-text">
              <span>Hotline CSKH</span>
              <strong>{shopInfo.hotline}</strong>
            </div>
          </a>
          {session ? (
            <div className="account-menu">
              <span className="account-greeting">Xin chào, {session.name}</span>
              {session.role === 'ADMIN' ? (
                <Link to="/dashboard" className="account-admin-link" aria-label="Quản trị">
                  <svg className="account-icon" width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                  <path d="M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm-7 8c1.2-4 4-6 7-6s5.8 2 7 6" stroke="currentColor" strokeWidth="1.6" fill="none" />
                </svg>
                <span className="account-text">Quản trị</span>
                </Link>
              ) : (
                <Link to="/tai-khoan" className="account-admin-link" aria-label="Tài khoản">
                  <svg className="account-icon" width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                  <path d="M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm-7 8c1.2-4 4-6 7-6s5.8 2 7 6" stroke="currentColor" strokeWidth="1.6" fill="none" />
                </svg>
                <span className="account-text">Tài khoản</span>
                </Link>
              )}
              <button className="account-logout" onClick={handleLogout}>
                Đăng xuất
              </button>
            </div>
          ) : (
            <IconButton label="Đăng nhập" to="/login">
              <path
                d="M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm-7 8c1.2-4 4-6 7-6s5.8 2 7 6"
                stroke="currentColor"
                strokeWidth="1.6"
                fill="none"
              />
            </IconButton>
          )}
          <Link to="/yeu-thich" className="icon-btn wish-link" aria-label={`Yêu thích (${wishCount})`}>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
              <path
                d="M12 20s-7-4.35-9.3-8.8C1.2 8 3 5 6.3 5c2 0 3.4 1.1 4.2 2.4C11.3 6.1 12.7 5 14.7 5 18 5 19.8 8 18.3 11.2 16 15.65 12 20 12 20Z"
                stroke="currentColor"
                strokeWidth="1.4"
                fill="none"
              />
            </svg>
            {wishCount > 0 && <span className="wish-count">{wishCount}</span>}
          </Link>
          <Link to="/gio-hang" className="cart">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
              <path
                d="M3 4h2l2 12h11l2-8H7"
                stroke="currentColor"
                strokeWidth="1.6"
                fill="none"
              />
              <circle cx="9" cy="20" r="1.4" fill="currentColor" />
              <circle cx="17" cy="20" r="1.4" fill="currentColor" />
            </svg>
            <span>
              <span className="cart-word">Giỏ hàng </span>
              {totalCount > 0 ? (
                <>
                  ({totalCount}) <span className="cart-total">{formatPrice(totalPrice)}</span>
                </>
              ) : (
                '0đ'
              )}
            </span>
          </Link>
        </div>
      </div>

      <div className="header-bottom">
        <div className="container header-bottom-inner">
          {/* Thứ tự: trang chủ -> xem sản phẩm -> cảm hứng/mẹo chọn -> độ tin cậy -> hỗ trợ tự phục vụ (hỏi đáp, tra cứu đơn) -> liên hệ trực tiếp */}
          <nav className="main-nav">
            <Link to="/" onClick={reloadIfHome}>Trang chủ</Link>
            <ProductsMenu />
            <Link to="/dat-rieng">Đặt riêng</Link>
            <Link to="/tin-tuc">Tin tức</Link>
            <Link to="/gioi-thieu">Giới thiệu</Link>
            <Link to="/cau-hoi-thuong-gap">Hỏi đáp</Link>
            <Link to="/tra-cuu-don-hang">Tra cứu đơn hàng</Link>
            <Link to="/lien-he">Liên hệ</Link>
          </nav>
        </div>
      </div>
      </div>
    </header>
  )
}

function IconButton({ label, children, to }) {
  const content = (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
      {children}
    </svg>
  )

  if (to) {
    return (
      <Link className="icon-btn" to={to} aria-label={label}>
        {content}
      </Link>
    )
  }

  return (
    <button className="icon-btn" aria-label={label}>
      {content}
    </button>
  )
}
